};

import type { Request, Response, NextFunction } from "express";
import { ZodError } from "zod";

export interface AppError {
  statusCode: number;
  code: string;
  message: string;
  details?: Array<{ field: string; message: string }>;
}

export function createAppError(
  statusCode: number,
  code: string,
  message: string,
  details?: Array<{ field: string; message: string }>
): AppError {
  return { statusCode, code, message, details };
}

function formatZodError(error: ZodError): AppError {
  const details = error.issues.map((issue) => ({
    field: issue.path.join("."),
    message: issue.message,
  }));
  return createAppError(400, "VALIDATION_ERROR", "数据验证失败", details);
}

function isAppError(err: unknown): err is AppError {
  return (
    typeof err === "object" &&
    err !== null &&
    "statusCode" in err &&
    "code" in err &&
    "message" in err
  );
}

export function errorHandler(
  err: Error,
  _req: Request,
  res: Response,
  _next: NextFunction
): void {
  // Zod validation errors
  if (err instanceof ZodError) {
    const appError = formatZodError(err);
    res.status(appError.statusCode).json({
      success: false,
      error: {
        code: appError.code,
        message: appError.message,
        details: appError.details,
      },
    });
    return;
  }

  // Known application errors
  if (isAppError(err)) {
    res.status(err.statusCode).json({
      success: false,
      error: {
        code: err.code,
        message: err.message,
        details: err.details,
      },
    });
    return;
  }

  // Unknown errors
  console.error("Unhandled error:", err);
  res.status(500).json({
    success: false,
    error: {
      code: "INTERNAL_ERROR",
      message: "服务器内部错误",
    },
  });
}

import morgan from "morgan";

export const requestLogger = morgan(
  process.env.NODE_ENV === "production" ? "combined" : "dev"
);

import type { Request, Response, NextFunction } from "express";
import { verifyToken } from "../utils/token.js";
import { createAppError } from "./errorHandler.js";

export function authMiddleware(
  req: Request,
  _res: Response,
  next: NextFunction
): void {
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    const error = createAppError(401, "UNAUTHORIZED", "未提供认证令牌");
    next(error);
    return;
  }

  const token = authHeader.slice(7);

  try {
    const payload = verifyToken(token);
    req.userId = payload.userId;
    next();
  } catch {
    const error = createAppError(401, "TOKEN_EXPIRED", "认证令牌无效或已过期");
    next(error);
  }
}

import type { Request, Response, NextFunction } from "express";
import type { ZodSchema } from "zod";

type RequestPart = "body" | "query" | "params";

export function validate(schema: ZodSchema, source: RequestPart = "body") {
  return (req: Request, _res: Response, next: NextFunction): void => {
    try {
      const parsed = schema.parse(req[source]);
      req[source] = parsed;
      next();
    } catch (error) {
      // Let the error handler deal with ZodError
      next(error);
    }
  };
}

import { getDatabase } from "../config/database.js";
import { v4 as uuidv4 } from "uuid";
import type { User, CreateUserInput, UserPublic } from "../types/user.js";

function toUserPublic(user: User): UserPublic {
  return {
    id: user.id,
    email: user.email,
    createdAt: user.createdAt,
    updatedAt: user.updatedAt,
  };
}

export function findUserByEmail(email: string): User | undefined {
  const db = getDatabase();
  const row = db
    .prepare(
      `SELECT id, email, password_hash as passwordHash, created_at as createdAt, updated_at as updatedAt
       FROM users WHERE email = ?`
    )
    .get(email) as User | undefined;
  return row;
}

export function findUserById(id: string): UserPublic | undefined {
  const db = getDatabase();
  const row = db
    .prepare(
      `SELECT id, email, created_at as createdAt, updated_at as updatedAt
       FROM users WHERE id = ?`
    )
    .get(id) as UserPublic | undefined;
  return row;
}

export function createUser(input: CreateUserInput, passwordHash: string): UserPublic {
  const db = getDatabase();
  const id = uuidv4();
  const now = new Date().toISOString();

  db.prepare(
    `INSERT INTO users (id, email, password_hash, created_at, updated_at)
     VALUES (?, ?, ?, ?, ?)`
  ).run(id, input.email, passwordHash, now, now);

  return {
    id,
    email: input.email,
    createdAt: now,
    updatedAt: now,
  };
}

import { getDatabase } from "../config/database.js";
import { v4 as uuidv4 } from "uuid";
import type {
  Task,
  CreateTaskInput,
  UpdateTaskInput,
  TaskQueryParams,
  TaskListResponse,
  PaginationMeta,
} from "../types/task.js";

const COLUMN_MAP: Record<string, string> = {
  due_date: "due_date",
  created_at: "created_at",
};

function mapRow(row: Record<string, unknown>): Task {
  return {
    id: row.id as string,
    userId: row.user_id as string,
    title: row.title as string,
    description: (row.description as string) ?? null,
    priority: row.priority as Task["priority"],
    status: row.status as Task["status"],
    dueDate: (row.due_date as string) ?? null,
    sortOrder: (row.sort_order as number) ?? null,
    createdAt: row.created_at as string,
    updatedAt: row.updated_at as string,
  };
}

export function findTasksByUserId(
  userId: string,
  params: TaskQueryParams
): TaskListResponse {
  const db = getDatabase();
  const conditions = ["user_id = ?"];
  const values: unknown[] = [userId];

  if (params.status) {
    conditions.push("status = ?");
    values.push(params.status);
  }

  if (params.priority) {
    conditions.push("priority = ?");
    values.push(params.priority);
  }

  const whereClause = conditions.join(" AND ");

  // Count total
  const countRow = db
    .prepare(`SELECT COUNT(*) as total FROM tasks WHERE ${whereClause}`)
    .get(...values) as { total: number };
  const total = countRow.total;

  // Pagination
  const page = params.page ?? 1;
  const limit = params.limit ?? 20;
  const offset = (page - 1) * limit;
  const totalPages = Math.ceil(total / limit);

  // Sorting
  const sortColumn = COLUMN_MAP[params.sortBy ?? "created_at"] ?? "created_at";
  const sortOrder = params.sortOrder === "asc" ? "ASC" : "DESC";

  const rows = db
    .prepare(
      `SELECT id, user_id, title, description, priority, status, due_date, sort_order, created_at, updated_at
       FROM tasks
       WHERE ${whereClause}
       ORDER BY ${sortColumn} ${sortOrder}
       LIMIT ? OFFSET ?`
    )
    .all(...values, limit, offset) as Record<string, unknown>[];

  const pagination: PaginationMeta = { page, limit, total, totalPages };

  return {
    tasks: rows.map(mapRow),
    pagination,
  };
}

export function findTaskById(id: string, userId: string): Task | undefined {
  const db = getDatabase();
  const row = db
    .prepare(
      `SELECT id, user_id, title, description, priority, status, due_date, sort_order, created_at, updated_at
       FROM tasks WHERE id = ? AND user_id = ?`
    )
    .get(id, userId) as Record<string, unknown> | undefined;

  return row ? mapRow(row) : undefined;
}

export function createTask(userId: string, input: CreateTaskInput): Task {
  const db = getDatabase();
  const id = uuidv4();
  const now = new Date().toISOString();

  db.prepare(
    `INSERT INTO tasks (id, user_id, title, description, priority, due_date, created_at, updated_at)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?)`
  ).run(
    id,
    userId,
    input.title,
    input.description ?? null,
    input.priority ?? "medium",
    input.dueDate ?? null,
    now,
    now
  );

  return {
    id,
    userId,
    title: input.title,
    description: input.description ?? null,
    priority: input.priority ?? "medium",
    status: "todo",
    dueDate: input.dueDate ?? null,
    sortOrder: null,
    createdAt: now,
    updatedAt: now,
  };
}

export function updateTask(
  id: string,
  userId: string,
  input: UpdateTaskInput
): Task | undefined {
  const db = getDatabase();
  const existing = findTaskById(id, userId);
  if (!existing) return undefined;

  const fields: string[] = [];
  const values: unknown[] = [];

  if (input.title !== undefined) {
    fields.push("title = ?");
    values.push(input.title);
  }
  if (input.description !== undefined) {
    fields.push("description = ?");
    values.push(input.description);
  }
  if (input.priority !== undefined) {
    fields.push("priority = ?");
    values.push(input.priority);
  }
  if (input.dueDate !== undefined) {
    fields.push("due_date = ?");
    values.push(input.dueDate);
  }

  if (fields.length === 0) return existing;

  const now = new Date().toISOString();
  fields.push("updated_at = ?");
  values.push(now);

  db.prepare(
    `UPDATE tasks SET ${fields.join(", ")} WHERE id = ? AND user_id = ?`
  ).run(...values, id, userId);

  return {
    ...existing,
    ...(input.title !== undefined && { title: input.title }),
    ...(input.description !== undefined && { description: input.description }),
    ...(input.priority !== undefined && { priority: input.priority }),
    ...(input.dueDate !== undefined && { dueDate: input.dueDate }),
    updatedAt: now,
  };
}

export function updateTaskStatus(
  id: string,
  userId: string,
  status: Task["status"]
): Task | undefined {
  const db = getDatabase();
  const existing = findTaskById(id, userId);
  if (!existing) return undefined;

  const now = new Date().toISOString();
  db.prepare(
    `UPDATE tasks SET status = ?, updated_at = ? WHERE id = ? AND user_id = ?`
  ).run(status, now, id, userId);

  return { ...existing, status, updatedAt: now };
}

export function deleteTask(id: string, userId: string): boolean {
  const db = getDatabase();
  const result = db
    .prepare(`DELETE FROM tasks WHERE id = ? AND user_id = ?`)
    .run(id, userId);

  return result.changes > 0;
}

import * as userModel from "../models/userModel.js";
import { hashPassword, comparePassword } from "../utils/password.js";
import { generateToken } from "../utils/token.js";
import { createAppError } from "../middleware/errorHandler.js";
import type { UserPublic, CreateUserInput } from "../types/user.js";

export interface AuthResult {
  token: string;
  expiresIn: number;
  user: UserPublic;
}

export async function register(input: CreateUserInput): Promise<UserPublic> {
  const existing = userModel.findUserByEmail(input.email);
  if (existing) {
    throw createAppError(409, "CONFLICT", "该邮箱已被注册");
  }

  const passwordHash = await hashPassword(input.password);
  return userModel.createUser(input, passwordHash);
}

export async function login(input: CreateUserInput): Promise<AuthResult> {
  const user = userModel.findUserByEmail(input.email);
  if (!user) {
    throw createAppError(401, "AUTH_FAILED", "邮箱或密码错误");
  }

  const valid = await comparePassword(input.password, user.passwordHash);
  if (!valid) {
    throw createAppError(401, "AUTH_FAILED", "邮箱或密码错误");
  }

  const token = generateToken({ userId: user.id, email: user.email });
  const expiresIn = 86400; // 24 hours in seconds

  return {
    token,
    expiresIn,
    user: {
      id: user.id,
      email: user.email,
      createdAt: user.createdAt,
      updatedAt: user.updatedAt,
    },
  };
}

export function getCurrentUser(userId: string): UserPublic {
  const user = userModel.findUserById(userId);
  if (!user) {
    throw createAppError(404, "NOT_FOUND", "用户不存在");
  }
  return user;
}

import * as taskModel from "../models/taskModel.js";
import { createAppError } from "../middleware/errorHandler.js";
import type {
  Task,
  CreateTaskInput,
  UpdateTaskInput,
  TaskQueryParams,
  TaskListResponse,
  TaskStatus,
} from "../types/task.js";

const VALID_TRANSITIONS: Record<TaskStatus, TaskStatus[]> = {
  todo: ["in_progress"],
  in_progress: ["completed"],
  completed: [],
};

export function getTasks(
  userId: string,
  params: TaskQueryParams
): TaskListResponse {
  return taskModel.findTasksByUserId(userId, params);
}

export function getTaskById(id: string, userId: string): Task {
  const task = taskModel.findTaskById(id, userId);
  if (!task) {
    throw createAppError(404, "NOT_FOUND", "任务不存在");
  }
  return task;
}

export function createTask(userId: string, input: CreateTaskInput): Task {
  return taskModel.createTask(userId, input);
}

export function updateTask(
  id: string,
  userId: string,
  input: UpdateTaskInput
): Task {
  const task = taskModel.updateTask(id, userId, input);
  if (!task) {
    throw createAppError(404, "NOT_FOUND", "任务不存在");
  }
  return task;
}

export function updateTaskStatus(
  id: string,
  userId: string,
  status: TaskStatus
): Task {
  const existing = taskModel.findTaskById(id, userId);
  if (!existing) {
    throw createAppError(404, "NOT_FOUND", "任务不存在");
  }

  const allowed = VALID_TRANSITIONS[existing.status];
  if (!allowed.includes(status)) {
    throw createAppError(
      400,
      "VALIDATION_ERROR",
      `不允许从 "${existing.status}" 转换为 "${status}"`
    );
  }

  const task = taskModel.updateTaskStatus(id, userId, status);
  if (!task) {
    throw createAppError(404, "NOT_FOUND", "任务不存在");
  }
  return task;
}

export function deleteTask(id: string, userId: string): void {
  const deleted = taskModel.deleteTask(id, userId);
  if (!deleted) {
    throw createAppError(404, "NOT_FOUND", "任务不存在");
  }
}

import type { Request, Response, NextFunction } from "express";
import * as authService from "../services/authService.js";
import type { RegisterInput, LoginInput } from "../validation/authValidation.js";

export async function register(
  req: Request,
  res: Response,
  next: NextFunction
): Promise<void> {
  try {
    const input = req.body as RegisterInput;
    const user = await authService.register({
      email: input.email,
      password: input.password,
    });

    res.status(201).json({
      success: true,
      message: "注册成功",
      data: user,
    });
  } catch (error) {
    next(error);
  }
}

export async function login(
  req: Request,
  res: Response,
  next: NextFunction
): Promise<void> {
  try {
    const input = req.body as LoginInput;
    const result = await authService.login({
      email: input.email,
      password: input.password,
    });

    res.status(200).json({
      success: true,
      data: result,
    });
  } catch (error) {
    next(error);
  }
}

export function getCurrentUser(
  req: Request,
